def parse_journal(path):
    data = open(path, 'rb').read()
    shard_id = int(os.path.basename(path).split('-')[1].split('.')[0])
    events = []
    off = 0
    while True:
        idx = data.find(b'JNL1', off)
        if idx < 0:
            break
        if idx + 24 > len(data):
            break
        ver, flags, typ, res = struct.unpack_from('<BBBB', data, idx+4)
        raw_len = struct.unpack_from('<I', data, idx+8)[0]
        seq = struct.unpack_from('<Q', data, idx+12)[0]
        crc = struct.unpack_from('<I', data, idx+20)[0]
        if ver == 1:
            plen = raw_len
        elif ver == 2:
            plen = raw_len ^ 0xA5A5A5A5
        else:
            off = idx + 1
            continue
        end = idx + 24 + plen
        if end > len(data):
            off = idx + 1
            continue
        frame = bytearray(data[idx:end])
        frame[20:24] = b'\x00\x00\x00\x00'
        calc = zlib.crc32(frame) & 0xffffffff
        if calc != crc:
            off = idx + 1
            continue
        payload = data[idx+24:end]
        if flags & 1:
            try:
                payload = zlib.decompress(payload)
            except Exception:
                off = idx + 1
                continue
        try:
            obj = json.loads(payload.decode('utf-8'))
        except Exception:
            off = idx + 1
            continue
        events.append({'shard_id': shard_id, 'seq': seq, 'type': typ, 'flags': flags, 'obj': obj})
        off = end
    return events

