        raw = struct.unpack_from('<I', data, m+8)[0]
        seq = struct.unpack_from('<Q', data, m+12)[0]
        stored_crc = struct.unpack_from('<I', data, m+20)[0]
        plen = raw if ver == 1 else (raw ^ 0xA5A5A5A5)
        end = m + 24 + plen
        if ver not in (1,2) or end > len(data):
            pos = m + 1
            continue
        frame = bytearray(data[m:end])
        frame[20:24] = b'\0\0\0\0'
        if (zlib.crc32(frame) & 0xffffffff) != stored_crc:
            pos = m + 1
            continue
        payload = data[m+24:end]
        if flags & 1:
            try: payload = zlib.decompress(payload)
            except Exception:
                pos = m + 1
                continue
        try: obj = json.loads(payload.decode())
        except Exception:
            pos = m + 1
            continue
        events.append({'shard': shard, 'seq': seq, 'type': typ, 'obj': obj})
        pos = end

# transfer completeness
legs = {}
for e in events:
    if e['type'] in (4,5):
        legs.setdefault(e['obj']['transfer_id'], set()).add(e['type'])
