    if not a['open']:
        a['held'].append((delta, ts))
    else:
        a['balance_minor'] += delta
        summary.setdefault(day(ts), {})
        summary[day(ts)][a['currency']] = summary[day(ts)].get(a['currency'], 0) + delta

